<?php
$stream = fopen('php://memory', 'w+');
fwrite($stream, "a\x00\x80\xffz");
rewind($stream);
echo bin2hex(fgetc($stream)), "\n";
ob_start();
$count = fpassthru(stream: $stream);
$bytes = ob_get_clean();
echo $count, ':', bin2hex($bytes), ':', ftell($stream), ':', (int)feof($stream), "\n";
var_dump(fpassthru($stream));
fseek($stream, 100);
var_dump(fpassthru($stream), ftell($stream));
rewind($stream);
ob_start();
echo '<';
$count = fpassthru($stream);
echo '>';
$bytes = ob_get_clean();
echo $count, ':', bin2hex($bytes), "\n";
fclose($stream);
$stream = fopen('php://memory', 'w+');
$payload = str_repeat('abc', 7001);
fwrite($stream, $payload);
fseek($stream, 17);
ob_start();
$count = fpassthru($stream);
$bytes = ob_get_clean();
var_dump($count, strlen($bytes), $bytes === substr($payload, 17), feof($stream));
fclose($stream);
